import { useMemo, useState } from "react";
import { Shuffle, ArrowUpRight } from "lucide-react";

type Category = "All" | "Case Study" | "Web" | "Mobile & Components";

type Project = {
  id: number;
  title: string;
  category: Exclude<Category, "All">;
  image: string;
  description?: string;
};

const projects: Project[] = [
  {
    id: 1,
    title: "AI Hiring Platform",
    category: "Case Study",
      image: "./landing page copy.png",
    description:
      "AI-powered hiring experience across onboarding, profile enrichment and interview preparation.",
  },
  {
    id: 2,
    title: "Conversational AI Agents",
    category: "Case Study",
    image: "./finura copy.png",
    description:
      "Multi-agent workflows, execution, analytics and a scalable design system.",
  },
  {
    id: 3,
    title: "Ninja Trader",
    category: "Web",
       image: "./foods copy.png",
    description:
      "Lending and payments experience designed for traders and low-digital-literacy users.",
  },
  {
    id: 4,
    title: "Digital Commerce",
    category: "Web",
    image: "./Skincare.png",
    description:
      "A simple and focused commerce experience across desktop and mobile.",
  },
  {
    id: 5,
    title: "Mobile Experience33",
    category: "Product",
    image: "./jweel copy.png",
    description:
      "Mobile-first product flows and reusable interface components.",
  },
  {
    id: 6,
    title: "Design System",
    category: "Mobile & Components",
    image: "./Skincare.png",
    description:
      "A flexible component system bringing consistency across products.",
  },
];

const categories: Category[] = [
  "All",
  "Case Study",
  "Web",
  "Mobile & Components",
];

export default function WorkPage() {
  const [activeCategory, setActiveCategory] = useState<Category>("All");
  const [shuffled, setShuffled] = useState(false);

  const filteredProjects = useMemo(() => {
    const filtered =
      activeCategory === "All"
        ? [...projects]
        : projects.filter(
            (project) => project.category === activeCategory
          );

    if (!shuffled) {
      return filtered;
    }

    return [...filtered].sort(() => Math.random() - 0.5);
  }, [activeCategory, shuffled]);

  const handleShuffle = () => {
    setShuffled((value) => !value);
  };

  return (
    <div className="min-h-screen bg-[#f7f5f2] text-neutral-950 transition-colors duration-300 dark:bg-[#111111] dark:text-neutral-100 ">
      {/* Page rails */}
      <div className="mx-auto min-h-screen w-full max-w-[820px]">
        <main className="px-6 py-8 sm:px-10 sm:py-12 lg:px-14">
          {/* Header */}
          <header>
            <p className="text-[18px] font-medium tracking-[-0.02em] text-neutral-500">
              Selected Work Showcase
            </p>
          </header>

          {/* Filters */}
          <div className="mt-14 flex flex-col justify-between gap-8 sm:flex-row sm:items-center">
            <div className="flex flex-wrap items-center gap-x-10 gap-y-4">
              {categories.map((category) => {
                const active = activeCategory === category;

                return (
                  <button
                  type="button"
                    key={category}
                    onClick={() => {
                      setActiveCategory(category);
                      setShuffled(false);
                    }}
                    className={`text-[18px] transition-colors duration-200 ${
                      active
                        ? "text-white"
                        : "text-neutral-500 hover:text-neutral-700"
                    }`}
                  >
                    {category}
                  </button>
                );
              })}
            </div>

            <button
            type="button"
              onClick={handleShuffle}
              className="group flex w-fit items-center gap-2 text-[18px] text-neutral-500 transition-colors hover:text-neutral-950"
            >
              <span>Shuffle</span>

              <Shuffle
                size={18}
                strokeWidth={1.6}
                className="transition-transform duration-300 group-hover:rotate-180"
              />
            </button>
          </div>

          {/* Project grid */}
          <section className="mt-20">
            {filteredProjects.length > 0 ? (
              <div className="grid grid-cols-1 gap-8 lg:grid-cols-2">
                {filteredProjects.map((project) => (
                  <article
                    key={project.id}
                    className="group cursor-pointer"
                  >
                    {/* Image frame */}
                    <div className="overflow-hidden bg-white p-4 sm:p-5">
                      <div className="relative aspect-[16/10] overflow-hidden border border-black/[0.07] bg-[#fafafa]">
                        <img
                          src={project.image}
                          alt={project.title}
                          className="h-full w-full object-cover transition-transform duration-700 ease-out group-hover:scale-[1.025]"
                        />

                        {/* Hover overlay */}
                        <div className="absolute inset-0 flex items-end justify-end bg-black/0 p-5 transition-colors duration-300 group-hover:bg-black/[0.04]">
                          <span className="flex h-11 w-11 translate-y-2 items-center justify-center rounded-full bg-white text-neutral-950 opacity-0 shadow-sm transition-all duration-300 group-hover:translate-y-0 group-hover:opacity-100">
                            <ArrowUpRight
                              size={20}
                              strokeWidth={1.6}
                            />
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Project information */}
                    <div className="flex items-start justify-between gap-6 px-1 pt-5">
                      <div>
                        <h2 className="text-[20px] font-medium tracking-[-0.02em]">
                          {project.title}
                        </h2>

                        <p className="mt-1 text-[16px] text-neutral-500">
                          {project.category}
                        </p>
                      </div>

                      <ArrowUpRight
                        size={20}
                        strokeWidth={1.5}
                        className="mt-1 text-neutral-400 transition-all duration-200 group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-neutral-950"
                      />
                    </div>
                  </article>
                ))}
              </div>
            ) : (
              <div className="border-t border-black/[0.1] py-20 text-center text-neutral-500">
                No projects in this category yet.
              </div>
            )}
          </section>
        </main>
      </div>
    </div>
  );
}
